/**
 * `--json` output helpers: field masks (`--fields`), the list envelope
 * (`{ items, nextPageToken }`), and client-side paging for list routes that
 * do not page on the server.
 */
import { CliUsageError } from "./errors.js";
export const DEFAULT_LIST_LIMIT = 20;
export const MAX_LIST_LIMIT = 100;
/** `--limit`, `--page-token`, and `--fields` as the list readers take them. */
export function listValues(values) {
    return {
        limit: values.limit === undefined ? undefined : Number(values.limit),
        pageToken: values["page-token"],
        fields: parseFields(values.fields),
    };
}
/** `--fields a,b.c` as a list of dot paths. */
export function parseFields(raw) {
    if (raw === undefined) {
        return undefined;
    }
    const fields = raw
        .split(",")
        .map((field) => field.trim())
        .filter((field) => field !== "");
    if (fields.length === 0) {
        throw new CliUsageError("--fields needs at least one field name");
    }
    return fields;
}
function isPlainObject(value) {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}
function pick(value, path) {
    if (path.length === 0) {
        return value;
    }
    if (Array.isArray(value)) {
        // Keep one slot per element so `merge` can align elements by index. An
        // element without the path becomes `{}`, not a JSON `null`, and an array
        // where no element has the path is left out.
        const picked = value.map((item) => pick(item, path));
        if (picked.every((item) => item === undefined)) {
            return undefined;
        }
        return picked.map((item) => item ?? {});
    }
    if (!isPlainObject(value)) {
        return undefined;
    }
    const [head, ...rest] = path;
    if (head === undefined || !(head in value)) {
        return undefined;
    }
    const child = pick(value[head], rest);
    return child === undefined ? undefined : { [head]: child };
}
function merge(target, source) {
    if (Array.isArray(target) && Array.isArray(source)) {
        return target.map((item, index) => merge(item, source[index]));
    }
    if (isPlainObject(target) && isPlainObject(source)) {
        const out = { ...target };
        for (const [key, value] of Object.entries(source)) {
            out[key] = key in out ? merge(out[key], value) : value;
        }
        return out;
    }
    return source === undefined ? target : source;
}
/**
 * Keep only the named dot paths of an object (or of each object in an
 * array). Paths that do not exist are left out. A path through an array
 * applies to each element.
 */
export function projectFields(value, fields) {
    if (fields === undefined) {
        return value;
    }
    if (Array.isArray(value)) {
        return value.map((item) => projectFields(item, fields));
    }
    if (!isPlainObject(value)) {
        return value;
    }
    let out = {};
    for (const field of fields) {
        const picked = pick(value, field.split("."));
        if (picked !== undefined) {
            out = merge(out, picked);
        }
    }
    return out;
}
/** Print one JSON document on stdout, with an optional field mask. */
export function printJson(value, options = {}) {
    const write = options.write ?? ((text) => void process.stdout.write(text));
    write(`${JSON.stringify(projectFields(value, options.fields), null, 2)}\n`);
}
/** Print a list page as `{ items, nextPageToken }`, masking each item. */
export function printListJson(page, options = {}) {
    const write = options.write ?? ((text) => void process.stdout.write(text));
    const items = page.items.map((item) => projectFields(item, options.fields));
    write(`${JSON.stringify({ items, nextPageToken: page.nextPageToken }, null, 2)}\n`);
}
const LOCAL_TOKEN_PREFIX = "offset:";
/**
 * One page of a list the server returns whole. The page token is the
 * offset of the next item, so it stays valid while the list does not change.
 */
export function pageLocally(all, options) {
    let offset = 0;
    if (options.pageToken !== undefined) {
        const raw = options.pageToken.startsWith(LOCAL_TOKEN_PREFIX)
            ? Number(options.pageToken.slice(LOCAL_TOKEN_PREFIX.length))
            : Number.NaN;
        if (!Number.isInteger(raw) || raw < 0) {
            throw new CliUsageError(`--page-token ${JSON.stringify(options.pageToken)} is not valid here`);
        }
        offset = raw;
    }
    const items = all.slice(offset, offset + options.limit);
    const next = offset + items.length;
    return {
        items,
        nextPageToken: next < all.length ? `${LOCAL_TOKEN_PREFIX}${next}` : null,
    };
}
/** The stderr line that tells a reader how to get the next page of a text table. */
export function nextPageHint(nextPageToken) {
    return nextPageToken === null ? undefined : `next page: --page-token ${nextPageToken}\n`;
}
